1	/// landlock.rs — Apply the Landlock LSM ruleset (INV-5, Linux ≥ 5.13).
2	///
3	/// Landlock is the kernel-side filesystem sandbox. The ruleset is the second
4	/// layer of defense behind `fs::validate()` (M1.2). Even if a future tool fn
5	/// forgets to validate(), the kernel will refuse opens that escape the rules
6	/// defined here.
7	///
8	/// Ruleset (matches `docs/phase1_roadmap.md` §M1.3):
9	///
10	///   READ-ONLY:
11	///     /proc, /sys     — kernel-exposed read-only data
12	///     /etc            — system config
13	///     /usr            — installed binaries / libs
14	///     /lib, /lib64    — dynamic loader / shared libs
15	///     /var/log        — system logs (mcpd's audit log lives in a sub-tree)
16	///     $HOME           — user files; writes there land in M1.5 with COW
17	///
18	///   READ-WRITE:
19	///     /tmp            — scratch
20	///     /var/log/mcpd   — mcpd's own audit log (M1.9)
21	///
22	/// Anything outside this list is denied by the kernel at `open()` time.
23	///
24	/// The crate API used here is `landlock = 0.4`. If the kernel doesn't
25	/// support Landlock, `apply()` hard-exits the process — running without the
26	/// sandbox is an INV-5 violation per CLAUDE.md.
27	use anyhow::{bail, Result};
28	use landlock::{
29	    Access, AccessFs, PathBeneath, PathFd, Ruleset, RulesetAttr,
30	    RulesetCreatedAttr, RulesetError, RulesetStatus, ABI,
31	};
32	use std::path::PathBuf;
33	use tracing::{info, warn};
34	
35	pub fn apply() -> Result<()> {
36	    // Use the minimum ABI we rely on. Newer kernels expose additional access
37	    // types we'd ignore here; landlock 0.4 surfaces that via
38	    // RulesetStatus::PartiallyEnforced — see match arms below.
39	    let abi = ABI::V1;
40	
41	    let home = std::env::var("HOME").unwrap_or_else(|_| "/root".into());
42	    let home_path = PathBuf::from(&home);
43	
44	    // Build the rule list as Results so PathFd::new failures can short-circuit
45	    // via add_rules() per landlock 0.4's IntoIterator<Item = Result<_, _>> API.
46	    let read_only_roots = [
47	        "/proc", "/sys", "/etc", "/usr", "/lib", "/lib64", "/var/log",
48	    ];
49	    let read_write_roots = ["/tmp", "/var/log/mcpd"];
50	
51	    let mut rules: Vec<std::result::Result<PathBeneath<PathFd>, RulesetError>> = Vec::new();
52	
53	    for p in read_only_roots {
54	        match PathFd::new(p) {
55	            Ok(fd) => rules.push(Ok(PathBeneath::new(fd, AccessFs::from_read(abi)))),
56	            Err(e) => warn!("landlock: skipping read-only root '{}': {}", p, e),
57	        }
58	    }
59	    for p in read_write_roots {
60	        match PathFd::new(p) {
61	            Ok(fd) => rules.push(Ok(PathBeneath::new(fd, AccessFs::from_all(abi)))),
62	            Err(e) => warn!("landlock: skipping read-write root '{}': {}", p, e),
63	        }
64	    }
65	    if home_path.exists() {
66	        match PathFd::new(&home_path) {
67	            Ok(fd) => rules.push(Ok(PathBeneath::new(fd, AccessFs::from_read(abi)))),
68	            Err(e) => warn!("landlock: skipping $HOME '{}': {}", home_path.display(), e),
69	        }
70	    }
71	
72	    let status = Ruleset::default()
73	        .handle_access(AccessFs::from_all(abi))?
74	        .create()?
75	        .add_rules(rules)?
76	        .restrict_self()?;
77	
78	    match status.ruleset {
79	        RulesetStatus::FullyEnforced => {
80	            info!("landlock: ABI v{} fully enforced", abi as u32);
81	            Ok(())
82	        }
83	        RulesetStatus::PartiallyEnforced => {
84	            warn!("landlock: only partially enforced (kernel missing some ABI features)");
85	            Ok(())
86	        }
87	        RulesetStatus::NotEnforced => {
88	            bail!(
89	                "landlock: NOT enforced after restrict_self() — kernel < 5.13? \
90	                 INV-5 violation. Aborting."
91	            );
92	        }
93	    }
94	}
