1	/// audit.rs — Append-only JSONL audit log (INV-8).
2	///
3	/// Every dispatched intent — including parse errors, schema rejects,
4	/// method-not-found, sandbox refuses, and COW-gated tickets — produces
5	/// exactly one line in the audit log. The log is opened with O_APPEND so
6	/// POSIX guarantees that writes ≤ PIPE_BUF (4096 bytes) are atomic across
7	/// concurrent writers. We keep each line under that ceiling by redacting
8	/// params and bounding payload size.
9	///
10	/// Default path:
11	///   Linux:  /var/log/mcpd/audit.log  (override: MCPD_AUDIT_LOG)
12	///   macOS:  /tmp/mcpd-audit.log      (dev only)
13	///
14	/// On open failure (permission denied, parent dir missing) the audit
15	/// writer falls back to stderr — the daemon continues but emits a one-time
16	/// warning. CLAUDE.md INV-8 says the audit log must not be writable by the
17	/// AI models; the systemd unit (Phase 6) chowns the parent dir to root:adm
18	/// with mode 0750.
19	use serde::Serialize;
20	use serde_json::Value;
21	use std::fs::OpenOptions;
22	use std::io::Write;
23	use std::path::PathBuf;
24	use std::sync::Mutex;
25	use std::sync::OnceLock;
26	
27	/// Result class — string union the Controller's audit consumer will dispatch on.
28	#[derive(Debug, Clone, Copy)]
29	pub enum ResultClass {
30	    Ok,
31	    Err,
32	    Refused,
33	    Unavailable,
34	    CowRequired,
35	    MethodNotFound,
36	    InvalidParams,
37	    ParseError,
38	}
39	
40	impl ResultClass {
41	    fn as_str(self) -> &'static str {
42	        match self {
43	            ResultClass::Ok               => "ok",
44	            ResultClass::Err              => "err",
45	            ResultClass::Refused          => "refused",
46	            ResultClass::Unavailable      => "unavailable",
47	            ResultClass::CowRequired      => "cow_required",
48	            ResultClass::MethodNotFound   => "method_not_found",
49	            ResultClass::InvalidParams    => "invalid_params",
50	            ResultClass::ParseError       => "parse_error",
51	        }
52	    }
53	}
54	
55	#[derive(Serialize)]
56	struct AuditLine<'a> {
57	    timestamp: String,
58	    method: &'a str,
59	    request_id: Option<&'a Value>,
60	    params_redacted: Value,
61	    result_class: &'static str,
62	    latency_us: u128,
63	}
64	
65	/// Persistent writer state. We use std::sync::Mutex (blocking) — writes are
66	/// rare and short, contention is negligible compared to async overhead.
67	struct Writer {
68	    file: Option<Mutex<std::fs::File>>,
69	}
70	
71	fn writer() -> &'static Writer {
72	    static W: OnceLock<Writer> = OnceLock::new();
73	    W.get_or_init(|| {
74	        let path = audit_path();
75	        // Best-effort: create parent dir if it doesn't exist.
76	        if let Some(parent) = path.parent() {
77	            let _ = std::fs::create_dir_all(parent);
78	        }
79	        let opened = OpenOptions::new()
80	            .create(true)
81	            .append(true)
82	            .mode_if_unix(0o640)
83	            .open(&path);
84	        match opened {
85	            Ok(f) => Writer { file: Some(Mutex::new(f)) },
86	            Err(e) => {
87	                tracing::warn!("audit: cannot open '{}': {}; falling back to stderr", path.display(), e);
88	                Writer { file: None }
89	            }
90	        }
91	    })
92	}
93	
94	fn audit_path() -> PathBuf {
95	    if let Ok(s) = std::env::var("MCPD_AUDIT_LOG") {
96	        return PathBuf::from(s);
97	    }
98	    #[cfg(target_os = "linux")]
99	    { PathBuf::from("/var/log/mcpd/audit.log") }
100	    #[cfg(not(target_os = "linux"))]
101	    { PathBuf::from("/tmp/mcpd-audit.log") }
102	}
103	
104	/// Convenience extension so we can call `.mode_if_unix(...)` without #[cfg]
105	/// noise at every call site.
106	trait OpenOptionsExt2 {
107	    fn mode_if_unix(&mut self, mode: u32) -> &mut Self;
108	}
109	impl OpenOptionsExt2 for OpenOptions {
110	    #[cfg(unix)]
111	    fn mode_if_unix(&mut self, mode: u32) -> &mut Self {
112	        use std::os::unix::fs::OpenOptionsExt;
113	        self.mode(mode)
114	    }
115	    #[cfg(not(unix))]
116	    fn mode_if_unix(&mut self, _mode: u32) -> &mut Self { self }
117	}
