119	/// Append one audit line. Never panics — even if the log file is unavailable,
120	/// the message goes to stderr.
121	pub fn log_intent(
122	    method: &str,
123	    request_id: Option<&Value>,
124	    params: &Value,
125	    result_class: ResultClass,
126	    latency_us: u128,
127	) {
128	    let line = AuditLine {
129	        timestamp: chrono::Utc::now().to_rfc3339(),
130	        method,
131	        request_id,
132	        params_redacted: redact(params),
133	        result_class: result_class.as_str(),
134	        latency_us,
135	    };
136	    let payload = match serde_json::to_string(&line) {
137	        Ok(s) => s,
138	        Err(e) => {
139	            tracing::error!("audit: serialize failed: {}", e);
140	            return;
141	        }
142	    };
143	
144	    // Truncate at 4 KB so the write fits within PIPE_BUF and stays atomic.
145	    let mut bytes = payload.into_bytes();
146	    if bytes.len() > 4000 {
147	        bytes.truncate(4000);
148	        bytes.extend_from_slice(b"...\"}");
149	    }
150	    bytes.push(b'\n');
151	
152	    match &writer().file {
153	        Some(mu) => {
154	            let mut guard = mu.lock().expect("audit mutex poisoned");
155	            let _ = guard.write_all(&bytes);
156	        }
157	        None => {
158	            eprintln!("[audit-fallback] {}", String::from_utf8_lossy(&bytes).trim_end());
159	        }
160	    }
161	}
162	
163	/// Redact path-like fields whose value is OUTSIDE the user's $HOME.
164	/// Limits info leak: a request like {"path": "/etc/shadow"} appears in the
165	/// audit log as {"path": "<redacted:/etc>"} so reviewers see the family of
166	/// the action without seeing the exact target.
167	fn redact(params: &Value) -> Value {
168	    let home = std::env::var("HOME").unwrap_or_else(|_| "/".into());
169	    redact_inner(params, &home)
170	}
171	
172	fn redact_inner(v: &Value, home: &str) -> Value {
173	    match v {
174	        Value::Object(map) => {
175	            let mut out = serde_json::Map::new();
176	            for (k, val) in map {
177	                if k == "content" {
178	                    // Never log raw write content — could include secrets.
179	                    out.insert(k.clone(), Value::String(format!("<redacted:{} bytes>",
180	                        val.as_str().map(|s| s.len()).unwrap_or(0))));
181	                } else if k == "path" {
182	                    if let Some(s) = val.as_str() {
183	                        if s.starts_with(home) {
184	                            out.insert(k.clone(), Value::String(s.to_string()));
185	                        } else {
186	                            let family = first_two_components(s);
187	                            out.insert(k.clone(), Value::String(format!("<redacted:{}>", family)));
188	                        }
189	                    } else {
190	                        out.insert(k.clone(), redact_inner(val, home));
191	                    }
192	                } else {
193	                    out.insert(k.clone(), redact_inner(val, home));
194	                }
195	            }
196	            Value::Object(out)
197	        }
198	        Value::Array(arr) => Value::Array(arr.iter().map(|x| redact_inner(x, home)).collect()),
199	        other => other.clone(),
200	    }
201	}
202	
203	/// Return the parent directory of an absolute path, used for redaction:
204	///   /etc/shadow          → "/etc"
205	///   /var/log/syslog      → "/var/log"
206	///   /etc                 → "/etc"   (already a top-level family)
207	///   relative or empty    → input
208	fn first_two_components(path: &str) -> String {
209	    let p = std::path::Path::new(path);
210	    if !p.is_absolute() {
211	        return path.to_string();
212	    }
213	    match p.parent() {
214	        // No parent (e.g. "/") or just "/" — return path as-is.
215	        None => path.to_string(),
216	        Some(parent) if parent.as_os_str() == "/" || parent.as_os_str().is_empty() => path.to_string(),
217	        Some(parent) => parent.to_string_lossy().into_owned(),
218	    }
219	}
