223	#[cfg(test)]
224	mod tests {
225	    use super::*;
226	    use serde_json::json;
227	
228	    #[test]
229	    fn redact_preserves_home_paths() {
230	        std::env::set_var("HOME", "/home/aditya");
231	        let v = redact(&json!({"path": "/home/aditya/notes.txt"}));
232	        assert_eq!(v["path"], "/home/aditya/notes.txt");
233	    }
234	
235	    #[test]
236	    fn redact_collapses_non_home_paths() {
237	        std::env::set_var("HOME", "/home/aditya");
238	        let v = redact(&json!({"path": "/etc/shadow"}));
239	        let s = v["path"].as_str().unwrap();
240	        assert!(s.starts_with("<redacted:"));
241	        assert!(s.contains("/etc"));
242	        assert!(!s.contains("shadow"));
243	    }
244	
245	    #[test]
246	    fn redact_truncates_content() {
247	        let v = redact(&json!({"path": "/tmp/x", "content": "secret-token-12345"}));
248	        let s = v["content"].as_str().unwrap();
249	        assert!(s.starts_with("<redacted:"));
250	        assert!(s.contains("18 bytes"));
251	    }
252	
253	    #[test]
254	    fn redact_handles_nested_objects() {
255	        std::env::set_var("HOME", "/home/aditya");
256	        let v = redact(&json!({"outer": {"path": "/etc/passwd"}}));
257	        assert!(v["outer"]["path"].as_str().unwrap().starts_with("<redacted:"));
258	    }
259	
260	    #[test]
261	    fn redact_passes_through_other_fields() {
262	        let v = redact(&json!({"unit": "nginx.service", "lines": 200}));
263	        assert_eq!(v["unit"], "nginx.service");
264	        assert_eq!(v["lines"], 200);
265	    }
266	
267	    #[test]
268	    fn first_two_components_etc_passwd() {
269	        assert_eq!(first_two_components("/etc/passwd"), "/etc");
270	        assert_eq!(first_two_components("/var/log/syslog"), "/var/log");
271	        assert_eq!(first_two_components("/boot/grub/x.cfg"), "/boot/grub");
272	    }
273	
274	    #[test]
275	    fn log_intent_does_not_panic_when_file_unavailable() {
276	        std::env::set_var("MCPD_AUDIT_LOG", "/dev/null/cannot-create");
277	        // Even with an unwritable path the call must not panic.
278	        log_intent("system.status", Some(&json!(1)), &json!({}), ResultClass::Ok, 100);
279	        std::env::remove_var("MCPD_AUDIT_LOG");
280	    }
281	}
