12	    tracing_subscriber::fmt()
13	        .with_env_filter(
14	            std::env::var("RUST_LOG").unwrap_or_else(|_| "mcpd=info".to_string()),
15	        )
16	        .with_writer(std::io::stderr) // logs to stderr; stdout is reserved for JSON-RPC
