19	    info!("mcpd starting — stdio JSON-RPC 2.0 server (schema {})", schema::SCHEMA_VERSION);
20	    info!("schema registry: {} methods", schema::registered_methods().count());
21	    info!("CRITICAL: No network listeners will be opened (INV-3)");
22	
